                       if (size < 1 || size > 3) {
                           continue;
                       }

                       PsiType type1 = parameters.get(0).getType();
                       if (!isContext(type1)) continue;

                       if (size == 1) {
                           hasValidConstructor = true;
                           break;
                       }

                       PsiType type2 = parameters.get(1).getType();
                       if (!isAttributeSet(type2)) continue;

                       if (size == 2) {
                           hasValidConstructor = true;
                           break;
                       }

                       PsiType type3 = parameters.get(2).getType();
                       if (isInt(type3)) {
                           hasValidConstructor = true;
                           break;
                       }
                   }

                   if (!hasValidConstructor) {
                       context.report(ISSUE, node, context.getNameLocation(node),
                           "Custom view `" + node.getName() + "` is missing constructor used by tools: " +
                           "`(Context)`, `(Context,AttributeSet)`, or `(Context,AttributeSet,int)`");
                   }
               }
           };
       }

       private static boolean isContext(PsiType type) {
           String text = type.getCanonicalText();
           return "android.content.Context".equals(text);
       }

       private static boolean isAttributeSet(PsiType type) {
           String text = type.getCanonicalText();
           return "android.util.AttributeSet".equals(text);
       }

       private static boolean isInt(PsiType type) {
           String text = type.getCanonicalText();
           return "int".equals(text) || "java.lang.Integer".equals(text);
       }
   }
   ```

